2	component: component.switch
3	package: "@taproot-ds/web-components"
4	tagName: ds-switch
5	defineExport: defineSwitch
6	usage: |
7	  <ds-switch label="Send desktop notifications" hint="Changes apply immediately." checked></ds-switch>
8	api:
9	  - { name: label, kind: attribute, parameter: label }
10	  - { name: hint, kind: attribute, parameter: hint }
11	  - { name: error, kind: attribute, parameter: error }
12	  - { name: checked, kind: attribute, parameter: checked }
13	  - { name: name, kind: attribute, parameter: name }
14	  - { name: value, kind: attribute, parameter: value }
15	  - { name: disabled, kind: attribute, parameter: disabled }
16	  - name: form
17	    kind: property
18	    type: "HTMLFormElement | null"
19	    description: The associated form, including association across the shadow boundary.
20	  - { name: input, kind: event, event: input }
21	  - { name: change, kind: event, event: change }
22	---
23	
24	Listen for `change` and apply the setting immediately. Read the live `checked` property.
25	If saving fails, restore the previous `checked` value and set `error` to explain the failure.
26	The `checked` attribute is the initial state; form reset restores it.
