13	export class DsSwitch extends ForwardsFocus(Base) {
14	  /** Lets ElementInternals submit the value across the shadow boundary. */
15	  static formAssociated = true;
16	
17	  static observedAttributes = ["checked", "disabled", "error", "hint", "label", "name", "value"];
18	
19	  #internals;
20	  #field;
21	  #label;
22	  #labelText;
23	  #input;
24	  #hint;
25	  #error;
26	  #formDisabled = false;
27	  /** Like a native checkbox's dirty checkedness: once set, the attribute no longer drives state. */
28	  #dirty = false;
29	
30	  constructor() {
31	    super();
32	    this.#internals = this.attachInternals();
33	
34	    const root = this.attachShadow({ mode: "open" });
35	    root.adoptedStyleSheets = [styleSheet()];
36	    root.innerHTML = `
37	      <div class="field" part="field">
38	        <div class="choice" part="choice">
39	          <span class="box">
40	            <input id="control" class="control" part="control" type="checkbox" role="switch" />
41	            <span class="indicator" part="indicator" aria-hidden="true"></span>
42	          </span>
43	          <label class="label" part="label" for="control">
44	            <span class="label-text"></span>
45	          </label>
46	        </div>
47	        <p id="hint" class="hint" part="hint" hidden></p>
48	        <p id="error" class="error" part="error" hidden aria-live="polite"></p>
49	      </div>
50	    `;
51	
52	    this.#field = root.querySelector(".field");
53	    this.#label = root.querySelector("label");
54	    this.#labelText = root.querySelector(".label-text");
55	    this.#input = root.querySelector("input");
56	    this.#hint = root.querySelector("#hint");
57	    this.#error = root.querySelector("#error");
58	
59	    this.#input.addEventListener("input", () => {
60	      this.#dirty = true;
61	      this.#syncFormValue();
62	      this.#syncValidity();
63	    });
64	    this.#input.addEventListener("change", this.#onChange);
65	    this.#input.addEventListener("invalid", this.#onInvalid);
66	    this.addEventListener("invalid", this.#onInvalid);
67	
68	    this.#input.checked = this.hasAttribute("checked");
69	    this.#render();
70	    this.#syncDisabled();
71	    this.#syncFormValue();
72	    this.#syncValidity();
73	  }
74	
75	  attributeChangedCallback(name, _old, value) {
76	    if (!this.#input) return;
77	
78	    if (name === "checked") {
79	      if (!this.#dirty) this.#input.checked = value != null;
80	    } else {
81	      this.#render();
82	      if (name === "disabled") this.#syncDisabled();
83	    }
84	    this.#syncFormValue();
85	    this.#syncValidity();
86	  }
87	
88	  /** Mirrors disabled state inherited from an ancestor <fieldset>. */
89	  formDisabledCallback(disabled) {
90	    this.#formDisabled = disabled;
91	    this.#syncDisabled();
92	    this.#syncFormValue();
93	  }
94	
95	  formResetCallback() {
96	    this.#dirty = false;
97	    this.#input.checked = this.hasAttribute("checked");
98	    this.#syncFormValue();
99	    this.#syncValidity();
100	  }
101	
102	  formStateRestoreCallback(state, mode) {
103	    if (state !== "checked" && state !== "unchecked") return;
104	    this.#input.checked = state === "checked";
105	    this.#dirty = mode === "restore";
106	    this.#syncFormValue();
107	    this.#syncValidity();
108	  }
109	
110	  get [focusTarget]() {
111	    return this.#input;
112	  }
113	
114	  /** The <form> this switch belongs to, or null. */
115	  get form() {
116	    return this.#internals.form;
117	  }
