123	  set label(value) {
124	    this.setAttribute("label", value ?? "");
125	  }
126	
127	  get hint() {
128	    return this.getAttribute("hint") ?? "";
129	  }
130	
131	  set hint(value) {
132	    this.#setOptionalAttribute("hint", value);
133	  }
134	
135	  get error() {
136	    return this.getAttribute("error") ?? "";
137	  }
138	
139	  set error(value) {
140	    this.#setOptionalAttribute("error", value);
141	  }
142	
143	  get name() {
144	    return this.getAttribute("name") ?? "";
145	  }
146	
147	  set name(value) {
148	    this.#setOptionalAttribute("name", value);
149	  }
150	
151	  /** Submitted when checked. Defaults to "on", as for a native checkbox. */
152	  get value() {
153	    return this.getAttribute("value") ?? "on";
154	  }
155	
156	  set value(value) {
157	    this.#setOptionalAttribute("value", value);
158	  }
159	
160	  get disabled() {
161	    return this.hasAttribute("disabled");
162	  }
163	
164	  set disabled(value) {
165	    this.toggleAttribute("disabled", Boolean(value));
166	  }
167	
168	  /** Live checked state. The attribute sets the initial state. */
169	  get checked() {
170	    return this.#input ? this.#input.checked : this.hasAttribute("checked");
171	  }
172	
173	  set checked(next) {
174	    this.#dirty = true;
175	    if (!this.#input) return;
176	    this.#input.checked = Boolean(next);
177	    this.#syncFormValue();
178	    this.#syncValidity();
179	  }
180	
181	  #setOptionalAttribute(name, value) {
182	    if (value == null || value === "") this.removeAttribute(name);
183	    else this.setAttribute(name, value);
184	  }
185	
186	  #render() {
187	    const label = this.label;
188	    this.#labelText.textContent = label;
189	    this.#label.hidden = label.length === 0;
190	
191	    const hint = this.hint;
192	    this.#hint.textContent = hint;
193	    this.#hint.hidden = hint.length === 0;
194	
195	    const error = this.error;
196	    this.#error.textContent = error;
197	    this.#error.hidden = error.length === 0;
198	
199	    this.#input.value = this.value;
200	
201	    const describedBy = [];
202	    if (hint) describedBy.push("hint");
203	    if (error) describedBy.push("error");
204	    if (describedBy.length > 0) this.#input.setAttribute("aria-describedby", describedBy.join(" "));
205	    else this.#input.removeAttribute("aria-describedby");
206	
207	    if (error) this.#input.setAttribute("aria-invalid", "true");
208	    else this.#input.removeAttribute("aria-invalid");
209	  }
210	
211	  #syncDisabled() {
212	    const disabled = this.disabled || this.#formDisabled;
213	    this.#input.disabled = disabled;
214	    this.#field.classList.toggle("is-disabled", disabled);
215	  }
216	
217	  #syncFormValue() {
218	    const checked = this.#input.checked;
219	    const state = checked ? "checked" : "unchecked";
220	    if (!checked || this.disabled || this.#formDisabled) {
221	      this.#internals.setFormValue(null, state);
222	      return;
223	    }
224	    this.#internals.setFormValue(this.value, state);
225	  }
226	
227	  #syncValidity() {
228	    const input = this.#input;
229	    const error = this.error;
230	    if (error) {
231	      this.#internals.setValidity({ customError: true }, error, input);
232	      return;
233	    }
234	    this.#internals.setValidity({});
235	  }
236	
237	  /** Native input crosses the shadow boundary; change is forwarded explicitly. */
238	  #onChange = () => {
239	    this.#dirty = true;
240	    this.#syncFormValue();
241	    this.#syncValidity();
242	    this.dispatchEvent(new Event("change", { bubbles: true }));
243	  };
244	
245	  /** Keep the visible error as the only validation message when one is set. */
246	  #onInvalid = (event) => {
247	    if (this.error) event.preventDefault();
248	  };
249	}
250	
251	/** Register the element. Safe to call more than once. Defaults to "ds-switch". */
252	export const defineSwitch = defineElement("ds-switch", DsSwitch);
